function Land({ k }: { k: string }) {
  return (
    <>
      <defs>
        {/* Se desvanece hacia la derecha: Europa occidental nítida, el resto se difumina */}
        <linearGradient id={`land-fade-${k}`} gradientUnits="userSpaceOnUse" x1="1000" y1="0" x2="1400" y2="0">
          <stop offset="0" stopColor="#fff" />
          <stop offset="1" stopColor="#000" />
        </linearGradient>
        <mask id={`land-mask-${k}`} maskUnits="userSpaceOnUse" x="-400" y="-400" width="2400" height="1600">
          <rect x="-400" y="-400" width="2400" height="1600" fill={`url(#land-fade-${k})`} />
        </mask>
      </defs>
    <g mask={`url(#land-mask-${k})`}>
      {/* Silueta de Europa y norte de África en un solo tono salvia */}
      <path d={LAND} fill="var(--accent)" fillOpacity="0.55" stroke="var(--primary)" strokeOpacity="0.75" strokeWidth="1.6" strokeLinejoin="round" />
    </g>
    </>
  );
}

