const baseProps = {
  "aria-hidden": true,
  focusable: "false" as const,
  fill: "none",
  stroke: "currentColor",
  strokeLinecap: "round" as const,
  strokeLinejoin: "round" as const,
};

export function TravelMap() {
  return (
    <>
      {/* Escritorio: dibujo ancho completo, anclado abajo */}
      <svg
        {...baseProps}
        viewBox="0 0 1600 720"
        preserveAspectRatio="xMidYMax meet"
        className="travel-map pointer-events-none absolute inset-0 hidden h-full w-full text-primary md:block"
      >
        <Drawing k="d" />
      </svg>
      {/* Móvil: solo la parte izquierda (Granada, Europa occidental, avión y barco) */}
      <svg
        {...baseProps}
        viewBox="190 360 560 360"
        preserveAspectRatio="xMinYMax meet"
        className="travel-map pointer-events-none absolute inset-0 h-full w-full text-primary md:hidden [mask-image:linear-gradient(to_bottom,transparent_16%,black_38%)]"
      >
        <Drawing k="m" />
      </svg>
    </>
  );
}
